window.AUTH=window.AUTH||{};window.AUTH["21-1333"]={"d":"21-1333","id":"2022/21-1333","n":"Gonzalez v. Google LLC","briefs":[{"k":"petitioner","label":"Brief of petitioners Reynaldo Gonzalez, et al.","date":"2022-11-30","url":"https://www.supremecourt.gov/DocketPDF/21/21-1333/247780/20221130182721608_GonzalezPetMerits.pdf","side":"pet","n":56},{"k":"united-states","label":"Brief amicus curiae of United States in support of vacatur","date":"2022-12-07","url":"https://www.supremecourt.gov/DocketPDF/21/21-1333/249441/20221207203557042_21-1333tsacUnitedStates.pdf","side":"pet","n":59},{"k":"respondent","label":"Brief of respondent Google LLC","date":"2023-01-12","url":"https://www.supremecourt.gov/DocketPDF/21/21-1333/252127/20230112144706745_Gonzalez%20v.%20Google%20Brief%20for%20Respondent%20-%20FINAL.pdf","side":"res","n":54},{"k":"reply","label":"Reply of petitioners Reynaldo Gonzalez, et al.","date":"2023-02-07","url":"https://www.supremecourt.gov/DocketPDF/21/21-1333/254251/20230207191257813_GonzalezRepyMeritsPrinted.pdf","side":"pet","n":20}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us2r25_i32j.pdf","tr":true,"items":[{"t":"case","label":"Barnes v. Yahoo!, Inc.","cite":"570 F.3d 1096","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/570/1096/","by":{"0":"18","1":"15","2":"25-26, 46-47, 52"}},{"t":"case","label":"Barr v. Matteo","cite":"360 U.S. 564","y":1959,"id":"1958/350","sc":1,"sum":"Justice John M. Harlan delivered the judgement of the court, reversing the court of appeals. The plurality argued that the statements from the press release were absolutely privileged. Justice Felix Frankfurter, Justice Tom C. Clark, and Justice Charles E. Whittaker joined in the plurality.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Blue Ridge Bank v. Veribanc, Inc.","cite":"866 F.2d 681","y":1989,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/866/681/","by":{"0":"23"}},{"t":"case","label":"Board of Governors, FRS v. Dimension Financial Corp.","cite":"474 U.S. 361","y":1986,"id":"1985/84-1274","sc":1,"sum":"The Board did not act within its statutory authority in defining \"banks\" as it did.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"51"}},{"t":"case","label":"Carafano v. Metrosplash.com, Inc.","cite":"339 F.3d 1119","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/339/1119/","by":{"0":"48","1":"12"}},{"t":"case","label":"Casteel v. News-Record, Inc.","cite":"875 P.2d 21","y":1994,"court":"Wyo.","url":"https://www.courtlistener.com/c/P.2d/875/21/","by":{"0":"23"}},{"t":"case","label":"Cipollone v. Ligget Corp., Inc.","cite":"505 U.S. 504","y":1992,"id":"1991/90-1038","sc":1,"sum":"In a complicated 7-to-2 decision, the Court held that federally mandated warnings do not bar smokers from suing manufacturers under state personal-injury laws. The justices ruled that such suits cannot be based on claims that cigarette advertising failed to warn smokers of smoking dangers.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"CTS Corporation v. Waldburger","cite":"573 U.S. 1","y":2014,"id":"2013/13-339","sc":1,"sum":"The Court found that the Comprehensive Environmental Response, Compensation, and Liability Act pre-empts statutes of limitations, but cannot be used to pre-empt statutes of repose.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Cubby, Inc. v. CompuServe, Inc.","cite":"776 F. Supp. 135","y":1991,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./776/135/","by":{"0":"4, 5","2":"8"}},{"t":"case","label":"Doe v. Internet Brands","cite":"824 F.3d 846","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/824/846/","op":4,"by":{"0":"25"}},{"t":"case","label":"Dyroff v. Ultimate Software Group, Inc.","cite":"934 F.3d 1093","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/934/1093/","ar":2,"by":{"0":"passim","2":"16, 38","3":"5, 7, 8, 10, 11, 18, 19, 21, 23"}},{"t":"case","label":"Erie Insurance Co. v. Amazon.com, Inc.","cite":"925 F.3d 135","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/925/135/","sum":"Holding section 230(c)(1) does not bar claim “based on” violation by defendant of its duty not to sell defective products.","sumSrc":"brief:0","by":{"0":"24","1":"15","2":"41"}},{"t":"case","label":"Fair Housing Council of San Fernando Valley v. Rommates.Com, LLC","cite":"521 F.3d 1157","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/521/1157/","ar":1,"by":{"0":"47","1":"13, 16, 17, 29","2":"29, 42","3":"23"}},{"t":"case","label":"Federal Trade Commission v. Match Group, Inc.","cite":"2022 WL 877107","y":2022,"court":"N.D. Tex. March 24","sum":"Holding section 230(c)(1) protects website recommendations of individuals of possible romantic interest that defendant knew were likely to be scams.","sumSrc":"brief:0","by":{"0":"35"}},{"t":"case","label":"Force v. Facebook, Inc.","cite":"934 F.3d 53","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/934/53/","ar":1,"by":{"0":"passim","1":"8, 13, 28, 31","2":"43, 45"}},{"t":"case","label":"Gaetano v. Sharon Herald Co.","cite":"426 Pa. 179","y":1967,"url":"https://www.courtlistener.com/c/Pa./426/179/","by":{"0":"21"}},{"t":"case","label":"Hall v. Hall","cite":"138 S. Ct. 1118","y":2018,"id":"2017/16-1150","sc":1,"sum":"The Court decided that when one of multiple cases consolidated under FRCP 42(a) is finally decided, that ruling confers upon the losing party the right to immediate appeal regardless of whether any of the other consolidated cases are still pending.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Henderson v. Source for Public Data, L.P.","cite":"2022 WL 16643916","y":2022,"court":"Nov. 3","by":{"0":"3, 24, 26"}},{"t":"case","label":"Herbert v. Lando","cite":"441 U.S. 153","y":1979,"id":"1978/77-1105","sc":1,"sum":"The Court reversed the decision of the Court of Appeals and held that the privilege not to answer editorial inquiries is not absolute. Justice White argued that shielding editorial decision-making from inquiry would \"substantially enhance the burden of proving actual malice,\" a burden which was already substantial in the Court's view.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Hoppe v. Hearst Corp.","cite":"53 Wash. App. 668","y":1989,"court":"Wash. Ct. App.","url":"https://www.courtlistener.com/c/Wash.%20App./53/668/","by":{"0":"23"}},{"t":"case","label":"Hutchinson v. Proxmire","cite":"443 U.S. 111","y":1979,"id":"1978/78-680","sc":1,"sum":"The Court affirmed the decision of the lower court and held that Proxmire's statements in his newsletters and press releases were not protected by the Speech and Debate Clause. However, in upholding this ruling, the Court also found that Proxmire's statements were not made with \"actual malice\" and thus, were not libelous.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Introini v. Richland County","cite":"1993 WL 73570","y":1993,"court":"D.S.C. Dec. 28","by":{"0":"23"}},{"t":"case","label":"Jones v. Dirty World Entertainment Recordings, LLC","cite":"755 F.3d 398","y":2014,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/755/398/","by":{"0":"48","2":"25, 30","3":"4"}},{"t":"case","label":"Lemmon v. Snap, Inc.","cite":"995 F.3d 1085","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/995/1085/","by":{"0":"25, 26"}},{"t":"case","label":"M.L. v. Craigslist, Inc.","cite":"2021 WL 5217115","y":2021,"court":"W.D. Wash. Sept. 16","op":1,"by":{"0":"41"}},{"t":"case","label":"Malwarebytes, Inc. v. Enigma Software Group USA, LLC","cite":"141 S. Ct. 13","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./141/13/","sc":1,"by":{"0":"7","1":"17, 18, 19, 21","2":"46, 48"}},{"t":"case","label":"New Prime, Inc. v. Oliviera","cite":"139 S. Ct. 532","y":2019,"id":"2018/17-340","sc":1,"sum":"A court should determine whether the Federal Arbitration Act’s §1 exclusion for disputes involving the “contracts of employment” of certain transportation workers applies before ordering arbitration; here, truck driver Oliveira’s independent contractor operating agreement with New Prime falls within that exception.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16, 51"}},{"t":"case","label":"New York Times v. Sullivan","cite":"376 U.S. 254","y":1964,"id":"1963/39","sc":1,"sum":"The Court held that the First Amendment protects freedom of speech and freedom of the press, even about the conduct of politicians, unless the statements are made with actual malice.","sumSrc":"Oyez","by":{"0":"21","2":"6, 49"}},{"t":"case","label":"Nodar v. Galbreath","cite":"462 So.2d 803","y":1984,"court":"Fla.","url":"https://www.courtlistener.com/c/So.2d/462/803/","by":{"0":"23"}},{"t":"case","label":"Peck v. Tribune Co.","cite":"214 U.S. 185","y":1909,"id":"scdb/1908-161","sc":1,"sum":"The publication of a portrait-with a statement thereunder imports '.that the original of. the portrait makes the statement even if another name be attached to the statement. Wandt v. Hearst’s Chicago American, 129 Wisconsin, 419; Morrison v. Smith, 177 N. Y. 366, approved on this point.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Stratton Oakmont, Inc. v. Prodigy Services Co.","cite":"1995 WL 323710","y":1995,"court":"Sup. Ct. N.Y. Cnty. May 24","ar":4,"by":{"0":"passim","1":"2, 3","2":"8, 50"}},{"t":"case","label":"Sunshine Sports Wear and Electronics, Inc. v. WSC Television Inc.","cite":"738 F. Supp. 1499","y":1989,"court":"D.S.C.","url":"https://www.courtlistener.com/c/F.%20Supp./738/1499/","by":{"0":"23"}},{"t":"case","label":"White v. Nichols","cite":"44 U.S. 266","y":1845,"id":"scdb/1845-032","sc":1,"op":1,"by":{"0":"21"}},{"t":"case","label":"Williams v. Trust Co. of Ga.","cite":"140 Ga. App. 45","y":1976,"court":"Ct. App.","url":"https://www.courtlistener.com/c/Ga.%20App./140/45/","ar":1,"by":{"0":"23"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"29","1":"3","2":"6, 30, 47-49, 52","3":"23"}},{"t":"usc","label":"18 U.S.C. § 1591","url":"https://www.law.cornell.edu/uscode/text/18/1591","stext":{"head":"§1591. Sex trafficking of children or by force, fraud, or coercion","paras":[[0,"(a) Whoever knowingly—"],[1,"(1) in or affecting interstate or foreign commerce, or within the special maritime and territorial jurisdiction of the United States, recruits, entices, harbors, transports, provides, obtains, advertises, maintains, patronizes, or solicits by any means a person; or"],[1,"(2) benefits, financially or by receiving anything of value, from participation in a venture which has engaged in an act described in violation of paragraph (1),"],[0,"knowing, or, except where the act constituting the violation of paragraph (1) is advertising, in reckless disregard of the fact, that means of force, threats of force, fraud, coercion described in subsection (e)(2), or any combination of such means will be used to cause the person to engage in a commercial sex act, or that the person has not attained the age of 18 years and will be caused to engage in a commercial sex act, shall be punished as provided in subsection (b)."],[0,"(b) The punishment for an offense under subsection (a) is—"],[1,"(1) if the offense was effected by means of force, threats of force, fraud, or coercion described in subsection (e)(2), or by any combination of such means, or if the person recruited, enticed, harbored, transported, provided, obtained, advertised, patronized, or solicited had not attained the age of 14 years at the time of such offense, by a fine under this title and imprisonment for any term of years not less than 15 or for life; or"],[1,"(2) if the offense was not so effected, and the person recruited, enticed, harbored, transported, provided, obtained, advertised, patronized, or solicited had attained the age of 14 years but had not attained the age of 18 years at the time of such offense, by a fine under this title and imprisonment for not less than 10 years or for life."],[0,"(c) In a prosecution under subsection (a)(1) in which the defendant had a reasonable opportunity to observe the person so recruited, enticed, harbored, transported, provided, obtained, maintained, patronized, or solicited, the Government need not prove that the defendant knew, or recklessly disregarded the fact, that the person had not attained the age of 18 years."],[0,"(d) Whoever obstructs, attempts to obstruct, or in any way interferes with or prevents the enforcement of this section, shall be fined under this title, imprisoned for a term not to exceed 25 years, or both."],[0,"(e) In this section:"],[1,"(1) The term \"abuse or threatened abuse of law or legal process\" means the use or threatened use of a law or legal process, whether administrative, civil, or criminal, in any manner or for any purpose for which the law was not designed, in order to exert pressure on another person to cause that person to take some action or refrain from taking some action."],[1,"(2) The term \"coercion\" means—"],[2,"(A) threats of serious harm to or physical restraint against any person;"],[2,"(B) any scheme, plan, or pattern intended to cause a person to believe that failure to perform an act would result in serious harm to or physical restraint against any person; or"],[2,"(C) the abuse or threatened abuse of law or the legal process."],[1,"(3) The term \"commercial sex act\" means any sex act, on account of which anything of value is given to or received by any person."],[1,"(4) The term \"participation in a venture\" means knowingly assisting, supporting, or facilitating a violation of subsection (a)(1)."],[1,"(5) The term \"serious harm\" means any harm, whether physical or nonphysical, including psychological, financial, or reputational harm, that is sufficiently serious, under all the surrounding circumstances, to compel a reasonable person of the same background and in the same circumstances to perform or to continue performing commercial sexual activity in order to avoid incurring that harm."],[1,"(6) The term \"venture\" means any group of two or more individuals associated in fact, whether or not a legal entity."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1591?type=usc&year=mostrecent&link-type=html"},"head":"§1591. Sex trafficking of children or by force, fraud, or coercion","tname":"Crimes and Criminal Procedure","by":{"0":"50","2":"47, 52"}},{"t":"usc","label":"18 U.S.C. § 2333","url":"https://www.law.cornell.edu/uscode/text/18/2333","subs":["(d)(2)","(a)","(d)"],"stext":{"head":"§2333. Civil remedies","paras":[[0,"(a) Action and Jurisdiction.—Any national of the United States injured in his or her person, property, or business by reason of an act of international terrorism, or his or her estate, survivors, or heirs, may sue therefor in any appropriate district court of the United States and shall recover threefold the damages he or she sustains and the cost of the suit, including attorney's fees."],[0,"(b) Estoppel Under United States Law.—A final judgment or decree rendered in favor of the United States in any criminal proceeding under section 1116, 1201, 1203, or 2332 of this title or section 46314, 46502, 46505, or 46506 of title 49 shall estop the defendant from denying the essential allegations of the criminal offense in any subsequent civil proceeding under this section."],[0,"(c) Estoppel Under Foreign Law.—A final judgment or decree rendered in favor of any foreign state in any criminal proceeding shall, to the extent that such judgment or decree may be accorded full faith and credit under the law of the United States, estop the defendant from denying the essential allegations of the criminal offense in any subsequent civil proceeding under this section."],[0,"(d) Liability.—"],[1,"(1) Definition.—In this subsection, the term \"person\" has the meaning given the term in section 1 of title 1."],[1,"(2) Liability.—In an action under subsection (a) for an injury arising from an act of international terrorism committed, planned, or authorized by an organization that had been designated as a foreign terrorist organization under section 219 of the Immigration and Nationality Act (8 U.S.C. 1189), as of the date on which such act of international terrorism was committed, planned, or authorized, liability may be asserted as to any person who aids and abets, by knowingly providing substantial assistance, or who conspires with the person who committed such an act of international terrorism."],[0,"(e) Use of Blocked Assets to Satisfy Judgments of U.S. Nationals.—For purposes of section 201 of the Terrorism Risk Insurance Act of 2002 (28 U.S.C. 1610 note), in any action in which a national of the United States has obtained a judgment against a terrorist party pursuant to this section, the term \"blocked asset\" shall include any asset of that terrorist party (including the blocked assets of any agency or instrumentality of that party) seized or frozen by the United States under section 805(b) of the Foreign Narcotics Kingpin Designation Act (21 U.S.C. 1904(b))."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2333?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2333. Civil remedies","tname":"Crimes and Criminal Procedure","by":{"0":"9, 48","1":"4, 25, 25, 5"}},{"t":"usc","label":"18 U.S.C. § 2421A","url":"https://www.law.cornell.edu/uscode/text/18/2421A","by":{"0":"50"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","by":{"0":"1"}},{"t":"usc","label":"47 U.S.C. § 230","url":"https://www.law.cornell.edu/uscode/text/47/230","subs":["(a)","(b)","(c)(1)","(c)(2)","(e)","(e)(1)","(e)(2)","(e)(3)","(e)(4)","(e)(5)(B)","(e)(5)(C)","(f)(2)","(a)(1)","(a)(3)","(b)(1)","(b)(4)","(c)","(e)(5)"],"stext":{"head":"§230. Protection for private blocking and screening of offensive material","paras":[[0,"(a) Findings"],[0,"The Congress finds the following:"],[1,"(1) The rapidly developing array of Internet and other interactive computer services available to individual Americans represent an extraordinary advance in the availability of educational and informational resources to our citizens."],[1,"(2) These services offer users a great degree of control over the information that they receive, as well as the potential for even greater control in the future as technology develops."],[1,"(3) The Internet and other interactive computer services offer a forum for a true diversity of political discourse, unique opportunities for cultural development, and myriad avenues for intellectual activity."],[1,"(4) The Internet and other interactive computer services have flourished, to the benefit of all Americans, with a minimum of government regulation."],[1,"(5) Increasingly Americans are relying on interactive media for a variety of political, educational, cultural, and entertainment services."],[0,"(b) Policy"],[0,"It is the policy of the United States—"],[1,"(1) to promote the continued development of the Internet and other interactive computer services and other interactive media;"],[1,"(2) to preserve the vibrant and competitive free market that presently exists for the Internet and other interactive computer services, unfettered by Federal or State regulation;"],[1,"(3) to encourage the development of technologies which maximize user control over what information is received by individuals, families, and schools who use the Internet and other interactive computer services;"],[1,"(4) to remove disincentives for the development and utilization of blocking and filtering technologies that empower parents to restrict their children's access to objectionable or inappropriate online material; and"],[1,"(5) to ensure vigorous enforcement of Federal criminal laws to deter and punish trafficking in obscenity, stalking, and harassment by means of computer."],[0,"(c) Protection for \"Good Samaritan\" blocking and screening of offensive material"],[0,"(1) Treatment of publisher or speaker"],[1,"No provider or user of an interactive computer service shall be treated as the publisher or speaker of any information provided by another information content provider."],[0,"(2) Civil liability"],[1,"No provider or user of an interactive computer service shall be held liable on account of—"],[2,"(A) any action voluntarily taken in good faith to restrict access to or availability of material that the provider or user considers to be obscene, lewd, lascivious, filthy, excessively violent, harassing, or otherwise objectionable, whether or not such material is constitutionally protected; or"],[2,"(B) any action taken to enable or make available to information content providers or others the technical means to restrict access to material described in paragraph (1).1"],[0,"(d) Obligations of interactive computer service"],[0,"A provider of interactive computer service shall, at the time of entering an agreement with a customer for the provision of interactive computer service and in a manner deemed appropriate by the provider, notify such customer that parental control protections (such as computer hardware, software, or filtering services) are commercially available that may assist the customer in limiting access to material that is harmful to minors. Such notice shall identify, or provide the customer with access to information identifying, current providers of such protections."],[0,"(e) Effect on other laws"],[0,"(1) No effect on criminal law"],[1,"Nothing in this section shall be construed to impair the enforcement of section 223 or 231 of this title, chapter 71 (relating to obscenity) or 110 (relating to sexual exploitation of children) of title 18, or any other Federal criminal statute."],[0,"(2) No effect on intellectual property law"],[1,"Nothing in this section shall be construed to limit or expand any law pertaining to intellectual property."],[0,"(3) State law"],[1,"Nothing in this section shall be construed to prevent any State from enforcing any State law that is consistent with this section. No cause of action may be brought and no liability may be imposed under any State or local law that is inconsistent with this section."],[0,"(4) No effect on communications privacy law"],[1,"Nothing in this section shall be construed to limit the application of the Electronic Communications Privacy Act of 1986 or any of the amendments made by such Act, or any similar State law."],[0,"(5) No effect on sex trafficking law"],[1,"Nothing in this section (other than subsection (c)(2)(A)) shall be construed to impair or limit—"],[2,"(A) any claim in a civil action brought under section 1595 of title 18, if the conduct underlying the claim constitutes a violation of section 1591 of that title;"],[2,"(B) any charge in a criminal prosecution brought under State law if the conduct underlying the charge would constitute a violation of section 1591 of title 18; or"],[2,"(C) any charge in a criminal prosecution brought under State law if the conduct underlying the charge would constitute a violation of section 2421A of title 18, and promotion or facilitation of prostitution is illegal in the jurisdiction where the defendant's promotion or facilitation of prostitution was targeted."],[0,"(f) Definitions"],[0,"As used in this section:"],[0,"(1) Internet"],[1,"The term \"Internet\" means the international computer network of both Federal and non-Federal interoperable packet switched data networks."],[0,"(2) Interactive computer service"],[1,"The term \"interactive computer service\" means any information service, system, or access software provider that provides or enables computer access by multiple users to a computer server, including specifically a service or system that provides access to the Internet and such systems operated or services offered by libraries or educational institutions."],[0,"(3) Information content provider"],[1,"The term \"information content provider\" means any person or entity that is responsible, in whole or in part, for the creation or development of information provided through the Internet or any other interactive computer service."],[0,"(4) Access software provider"],[1,"The term \"access software provider\" means a provider of software (including client or server software), or enabling tools that do any one or more of the following:"],[2,"(A) filter, screen, allow, or disallow content;"],[2,"(B) pick, choose, analyze, or digest content; or"],[2,"(C) transmit, receive, display, forward, cache, search, subset, organize, reorganize, or translate content."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/230?type=usc&year=mostrecent&link-type=html"},"op":5,"ar":9,"head":"§230. Protection for private blocking and screening of offensive material","tname":"Telecommunications","by":{"0":"passim, 47, 46, 47, passim, 7, 50, 47, 50, 48, 50, 51, 50, 50, 50, passim","1":"1, passim, 3, 3, 15, 1, 3, 4, 15, 4, passim, 4, 4, 19, 8, 13, 23, 33, 9, 21, 22, 29, 23, 23, 23","2":"3-5, 7-10, 14, 17, 19-22, 26, 30-36, 39-40, 46-55, 9, 18, 22, 26, 35-36","3":"22, 1, 2–11, 13–25, 15, 17"}},{"t":"usc","label":"18 U.S.C. § 2331","url":"https://www.law.cornell.edu/uscode/text/18/2331","stext":{"head":"§2331. Definitions","paras":[[0,"As used in this chapter—"],[1,"(1) the term \"international terrorism\" means activities that—"],[2,"(A) involve violent acts or acts dangerous to human life that are a violation of the criminal laws of the United States or of any State, or that would be a criminal violation if committed within the jurisdiction of the United States or of any State;"],[2,"(B) appear to be intended—"],[3,"(i) to intimidate or coerce a civilian population;"],[3,"(ii) to influence the policy of a government by intimidation or coercion; or"],[3,"(iii) to affect the conduct of a government by mass destruction, assassination, or kidnapping; and"],[2,"(C) occur primarily outside the territorial jurisdiction of the United States, or transcend national boundaries in terms of the means by which they are accomplished, the persons they appear intended to intimidate or coerce, or the locale in which their perpetrators operate or seek asylum;"],[1,"(2) the term \"national of the United States\" has the meaning given such term in section 101(a)(22) of the Immigration and Nationality Act;"],[1,"(3) the term \"person\" means any individual or entity capable of holding a legal or beneficial interest in property;"],[1,"(4) the term \"act of war\" means any act occurring in the course of—"],[2,"(A) declared war;"],[2,"(B) armed conflict, whether or not war has been declared, between two or more nations; or"],[2,"(C) armed conflict between military forces of any origin;"],[1,"(5) the term \"domestic terrorism\" means activities that—"],[2,"(A) involve acts dangerous to human life that are a violation of the criminal laws of the United States or of any State;"],[2,"(B) appear to be intended—"],[3,"(i) to intimidate or coerce a civilian population;"],[3,"(ii) to influence the policy of a government by intimidation or coercion; or"],[3,"(iii) to affect the conduct of a government by mass destruction, assassination, or kidnapping; and"],[2,"(C) occur primarily within the territorial jurisdiction of the United States; and"],[1,"(6) the term \"military force\" does not include any person that—"],[2,"(A) has been designated as a—"],[3,"(i) foreign terrorist organization by the Secretary of State under section 219 of the Immigration and Nationality Act (8 U.S.C. 1189); or"],[3,"(ii) specially designated global terrorist (as such term is defined in section 594.310 of title 31, Code of Federal Regulations) by the Secretary of State or the Secretary of the Treasury; or"],[2,"(B) has been determined by the court to not be a \"military force\"."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2331?type=usc&year=mostrecent&link-type=html"},"head":"§2331. Definitions","tname":"Crimes and Criminal Procedure","by":{"0":"48","1":"4"}},{"t":"case","label":"Cianci v. New Times Publ’g Co.","cite":"639 F.2d 54","y":1980,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/639/54/","by":{"1":"3"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Dennis v. MyLife.Com, Inc.","cite":"2021 WL 6049830","y":2021,"court":"D.N.J. Dec. 20","sum":"Holding that a background-check site could not face liability for a “reputation score” it generated, because the score was based on information originating from others.","sumSrc":"brief:1","by":{"1":"24"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"138 S. Ct. 1134","y":2018,"id":"2017/16-1362","sc":1,"sum":"The Court decided that because service advisors at car dealerships are “salesm[e]n . . . primarily engaged in . . . servicing automobiles,” 29 U.S.C. § 213(b)(10)(A), they are exempt from the Fair Labor Standards Act's overtime-pay requirements.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"FCC v. AT&T Inc.","cite":"562 U.S. 397","y":2011,"id":"2010/09-1279","sc":1,"sum":"The Court held that corporations do not have a right of personal privacy that would prevent the disclosure of public records handed over to federal agencies.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"FTC v. Accusearch Inc.","cite":"570 F.3d 1187","y":2009,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/570/1187/","sum":"Explaining that “there may be several information content providers with respect to a single item of information”.","sumSrc":"brief:1","by":{"1":"21, 22"}},{"t":"case","label":"Gertz v. Robert Welch, Inc.","cite":"418 U.S. 323","y":1974,"id":"1973/72-617","sc":1,"sum":"Private individuals need only prove negligence to recover in defamation suits against news media","sumSrc":"Oyez","by":{"1":"3","2":"6, 49"}},{"t":"case","label":"Getachew v. Google, Inc.","cite":"491 Fed. Appx. 923","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./491/923/","by":{"1":"29"}},{"t":"case","label":"Henderson v. The Source for Public Data, L.P.","cite":"53 F.4th 110","y":2022,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/53/110/","sum":"Holding that a background-check site could not face liability for a “reputation score” it generated, because the score was based on information originating from others.","sumSrc":"brief:1","by":{"1":"16, 24","2":"28-29","3":"3, 7, 20"}},{"t":"case","label":"Jane Doe No. 1 v. Backpage.com, LLC","cite":"817 F.3d 12","y":2016,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/817/12/","by":{"1":"18, 19","2":"26, 31, 42"}},{"t":"case","label":"Levitt v. Yelp! Inc.","cite":"2011 WL 5079526","y":2011,"court":"N.D. Cal. Oct. 26","by":{"1":"16","2":"42"}},{"t":"case","label":"Marshall’s Locksmith Serv., Inc. v. Google, LLC","cite":"925 F.3d 1268","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/925/1268/","by":{"1":"13, 29"}},{"t":"case","label":"O’Kroley v. Fastcase, Inc.","cite":"831 F.3d 352","y":2016,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/831/352/","by":{"1":"29","2":"28"}},{"t":"case","label":"Quarles v. United States","cite":"139 S. Ct. 1872","y":2019,"id":"2018/17-778","sc":1,"sum":"Michigan’s third-degree home-invasion statute substantially corresponds to or is narrower than generic burglary for purposes of qualifying for enhanced sentencing under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"23"}},{"t":"case","label":"Reno v. American Civil Liberties Union","cite":"521 U.S. 844","y":1997,"id":"1996/96-511","sc":1,"sum":"The Court ruled that certain provisions of the Communications Decency Act concerning \"indecent\" behavior were unconstitutionally vague.","sumSrc":"Oyez","by":{"1":"2, 21, 33","3":"15, 16"}},{"t":"case","label":"Universal Commc’n Sys., Inc. v. Lycos, Inc.","cite":"478 F.3d 413","y":2007,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/478/413/","by":{"1":"12, 21"}},{"t":"case","label":"Zeran v. America Online, Inc.","cite":"129 F.3d 327","y":1997,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/129/327/","ar":1,"by":{"1":"13, 15, 17, 18, 20","2":"30-31","3":"6, 7"}},{"t":"law","label":"Pub. L. No. 115-164","url":"https://www.govinfo.gov/link/plaw/115/public/164","by":{"1":"19"}},{"t":"law","label":"Child Online Protection Act, Pub. L. No. 105-277","url":"https://www.govinfo.gov/link/plaw/105/public/277","by":{"1":"33"}},{"t":"usc","label":"47 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/47/151","by":{"1":"1"}},{"t":"usc","label":"47 U.S.C. § 207","url":"https://www.law.cornell.edu/uscode/text/47/207","by":{"1":"21"}},{"t":"law","label":"Pub. L. No. 104-104","url":"https://www.govinfo.gov/link/plaw/104/public/104","by":{"1":"2, 1"}},{"t":"usc","label":"47 U.S.C. § 223","url":"https://www.law.cornell.edu/uscode/text/47/223","subs":["(d)(1)(B)","(e)(6)"],"by":{"1":"21, 20, 21, 21"}},{"t":"usc","label":"47 U.S.C. § 231","url":"https://www.law.cornell.edu/uscode/text/47/231","subs":["(a)(1)","(b)(3)","(e)(5)"],"stext":{"head":"§231. Restriction of access by minors to materials commercially distributed by means of World Wide Web that are harmful to minors","paras":[[0,"(a) Requirement to restrict access"],[0,"(1) Prohibited conduct"],[1,"Whoever knowingly and with knowledge of the character of the material, in interstate or foreign commerce by means of the World Wide Web, makes any communication for commercial purposes that is available to any minor and that includes any material that is harmful to minors shall be fined not more than $50,000, imprisoned not more than 6 months, or both."],[0,"(2) Intentional violations"],[1,"In addition to the penalties under paragraph (1), whoever intentionally violates such paragraph shall be subject to a fine of not more than $50,000 for each violation. For purposes of this paragraph, each day of violation shall constitute a separate violation."],[0,"(3) Civil penalty"],[1,"In addition to the penalties under paragraphs (1) and (2), whoever violates paragraph (1) shall be subject to a civil penalty of not more than $50,000 for each violation. For purposes of this paragraph, each day of violation shall constitute a separate violation."],[0,"(b) Inapplicability of carriers and other service providers"],[0,"For purposes of subsection (a), a person shall not be considered to make any communication for commercial purposes to the extent that such person is—"],[1,"(1) a telecommunications carrier engaged in the provision of a telecommunications service;"],[1,"(2) a person engaged in the business of providing an Internet access service;"],[1,"(3) a person engaged in the business of providing an Internet information location tool; or"],[1,"(4) similarly engaged in the transmission, storage, retrieval, hosting, formatting, or translation (or any combination thereof) of a communication made by another person, without selection or alteration of the content of the communication, except that such person's deletion of a particular communication or material made by another person in a manner consistent with subsection (c) or section 230 of this title shall not constitute such selection or alteration of the content of the communication."],[0,"(c) Affirmative defense"],[0,"(1) Defense"],[1,"It is an affirmative defense to prosecution under this section that the defendant, in good faith, has restricted access by minors to material that is harmful to minors—"],[2,"(A) by requiring use of a credit card, debit account, adult access code, or adult personal identification number;"],[2,"(B) by accepting a digital certificate that verifies age; or"],[2,"(C) by any other reasonable measures that are feasible under available technology."],[0,"(2) Protection for use of defenses"],[1,"No cause of action may be brought in any court or administrative agency against any person on account of any activity that is not in violation of any law punishable by criminal or civil penalty, and that the person has taken in good faith to implement a defense authorized under this subsection or otherwise to restrict or prevent the transmission of, or access to, a communication specified in this section."],[0,"(d) Privacy protection requirements"],[0,"(1) Disclosure of information limited"],[1,"A person making a communication described in subsection (a)—"],[2,"(A) shall not disclose any information collected for the purposes of restricting access to such communications to individuals 17 years of age or older without the prior written or electronic consent of—"],[3,"(i) the individual concerned, if the individual is an adult; or"],[3,"(ii) the individual's parent or guardian, if the individual is under 17 years of age; and"],[2,"(B) shall take such actions as are necessary to prevent unauthorized access to such information by a person other than the person making such communication and the recipient of such communication."],[0,"(2) Exceptions"],[1,"A person making a communication described in subsection (a) may disclose such information if the disclosure is—"],[2,"(A) necessary to make the communication or conduct a legitimate business activity related to making the communication; or"],[2,"(B) made pursuant to a court order authorizing such disclosure."],[0,"(e) Definitions"],[0,"For purposes of this subsection,1 the following definitions shall apply:"],[0,"(1) By means of the World Wide Web"],[1,"The term \"by means of the World Wide Web\" means by placement of material in a computer server-based file archive so that it is publicly accessible, over the Internet, using hypertext transfer protocol or any successor protocol."],[0,"(2) Commercial purposes; engaged in the business"],[0,"(A) Commercial purposes"],[2,"A person shall be considered to make a communication for commercial purposes only if such person is engaged in the business of making such communications."],[0,"(B) Engaged in the business"],[2,"The term \"engaged in the business\" means that the person who makes a communication, or offers to make a communication, by means of the World Wide Web, that includes any material that is harmful to minors, devotes time, attention, or labor to such activities, as a regular course of such person's trade or business, with the objective of earning a profit as a result of such activities (although it is not necessary that the person make a profit or that the making or offering to make such communications be the person's sole or principal business or source of income). A person may be considered to be engaged in the business of making, by means of the World Wide Web, communications for commercial purposes that include material that is harmful to minors, only if the person knowingly causes the material that is harmful to minors to be posted on the World Wide Web or knowingly solicits such material to be posted on the World Wide Web."],[0,"(3) Internet"],[1,"The term \"Internet\" means the combination of computer facilities and electromagnetic transmission media, and related equipment and software, comprising the interconnected worldwide network of computer networks that employ the Transmission Control Protocol/Internet Protocol or any successor protocol to transmit information."],[0,"(4) Internet access service"],[1,"The term \"Internet access service\" means a service that enables users to access content, information, electronic mail, or other services offered over the Internet, and may also include access to proprietary content, information, and other services as part of a package of services offered to consumers. Such term does not include telecommunications services."],[0,"(5) Internet information location tool"],[1,"The term \"Internet information location tool\" means a service that refers or links users to an online location on the World Wide Web. Such term includes directories, indices, references, pointers, and hypertext links."],[0,"(6) Material that is harmful to minors"],[1,"The term \"material that is harmful to minors\" means any communication, picture, image, graphic image file, article, recording, writing, or other matter of any kind that is obscene or that—"],[2,"(A) the average person, applying contemporary community standards, would find, taking the material as a whole and with respect to minors, is designed to appeal to, or is designed to pander to, the prurient interest;"],[2,"(B) depicts, describes, or represents, in a manner patently offensive with respect to minors, an actual or simulated sexual act or sexual contact, an actual or simulated normal or perverted sexual act, or a lewd exhibition of the genitals or post-pubescent female breast; and"],[2,"(C) taken as a whole, lacks serious literary, artistic, political, or scientific value for minors."],[0,"(7) Minor"],[1,"The term \"minor\" means any person under 17 years of age."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/231?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§231. Restriction of access by minors to materials commercially distributed by means of World Wide Web that are harmful to minors","tname":"Telecommunications","by":{"1":"33, 34, 34, 34"}},{"t":"law","label":"Justice Against Sponsors of Terrorism Act, Pub. L. No. 114-222","url":"https://www.govinfo.gov/link/plaw/114/public/222","by":{"1":"4"}},{"t":"case","label":"Barrett v. Rosenthal","cite":"146 P.3d 510","y":2006,"court":"Cal.","url":"https://www.courtlistener.com/c/P.3d/146/510/","by":{"2":"54"}},{"t":"case","label":"Ben Ezra, Weinstein, & Co. v. Am. Online","cite":"206 F.3d 980","y":2000,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/206/980/","by":{"2":"25"}},{"t":"case","label":"Brown v. Kelly Broad. Co.","cite":"771 P.2d 406","y":1989,"court":"Cal.","url":"https://www.courtlistener.com/c/P.2d/771/406/","by":{"2":"49"}},{"t":"case","label":"Cardozo v. True","cite":"342 So.2d 1053","y":1977,"court":"Fla. Dist. Ct. App.","url":"https://www.courtlistener.com/c/So.2d/342/1053/","by":{"2":"7"}},{"t":"case","label":"Church of Scientology v. Minn. State Med. Ass’n Found.","cite":"264 N.W.2d 152","y":1978,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W.2d/264/152/","by":{"2":"48"}},{"t":"case","label":"City & County of San Francisco v. Sheehan","cite":"575 U.S. 600","y":2015,"id":"2014/13-1412","sc":1,"sum":"The Court held that an unwarranted entry does not violate the Fourth Amendment when it does not violate a clearly established constitutional or statutory right and is reasonable under the circumstances.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"Dunn v. Hall","cite":"1 Ind. 344","y":1849,"url":"https://www.courtlistener.com/c/Ind./1/344/","by":{"2":"5"}},{"t":"case","label":"FTC v. LeadClick Media, LLC","cite":"838 F.3d 158","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/838/158/","by":{"2":"25"}},{"t":"case","label":"Goldstein v. Garlick","cite":"318 N.Y.S.2d 370","y":1971,"court":"Sup. Ct.","url":"https://www.courtlistener.com/c/N.Y.S.2d/318/370/","by":{"2":"7"}},{"t":"case","label":"Hurley v. Irish-Am. Gay, Lesbian & Bisexual Grp. of Bos.","cite":"515 U.S. 557","y":1995,"id":"1994/94-749","sc":1,"sum":"A unanimous court held that the State Court's ruling to require private citizens who organize a parade to include a group expressing a message that the organizers do not wish to convey violates the First Amendment by making private speech subordinate to the public accommodation requirement.","sumSrc":"Oyez","by":{"2":"24-25","3":"13"}},{"t":"case","label":"Hustler Mag., Inc. v. Falwell","cite":"485 U.S. 46","y":1988,"id":"1987/86-1278","sc":1,"sum":"The Court ruled that the First Amendment's freedom of speech protection extended to the making of clearly offensive statements about public figures, so long as such speech could not reasonably be construed to convey facts about its subject.","sumSrc":"Oyez","by":{"2":"47"}},{"t":"case","label":"Johnson v. Arden","cite":"614 F.3d 785","y":2010,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/614/785/","by":{"2":"25"}},{"t":"case","label":"The King v. Woodfall","cite":"98 Eng. Rep. 914","y":1774,"url":"https://www.courtlistener.com/c/Eng.%20Rep./98/914/","by":{"2":"5"}},{"t":"case","label":"Klayman v. Zuckerberg","cite":"753 F.3d 1354","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/753/1354/","by":{"2":"25, 30"}},{"t":"case","label":"Manhattan Cmty. Access Corp. v. Halleck","cite":"139 S. Ct. 1921","y":2019,"id":"2018/17-1702","sc":1,"sum":"The Court held that Manhattan Community Access Corp, which operates public access channels, is not a state actor subject to constitutional liability.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Manual Enters. v. Day","cite":"370 U.S. 478","y":1962,"id":"1961/123","sc":1,"sum":"The judgment is reversed. Pp. 479-519. 110 U. S. App. D. C. 78, 289 F. 2d 455, reversed. MR. JUSTICE HARLAN, joined by MR. JUSTICE STEWART, concluded that:","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"7"}},{"t":"case","label":"Marshall’s Locksmith Serv. v. Google, LLC","cite":"925 F.3d 1263","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/925/1263/","by":{"2":"9, 21"}},{"t":"case","label":"Metro-Goldwyn-Mayer Studios v. Grokster, Ltd.","cite":"545 U.S. 913","y":2005,"id":"2004/04-480","sc":1,"sum":"The Court ruled that companies that distributed file-sharing software, and encouraged and profited from direct copyright infringement using such software, were liable for the infringement.","sumSrc":"Oyez","by":{"2":"51"}},{"t":"case","label":"Mia. Herald Publ’g Co. v. Tornillo","cite":"418 U.S. 241","y":1974,"id":"1973/73-797","sc":1,"sum":"The Court reversed the Supreme Court of Florida and held that Florida's \"right to reply\" statute violated the freedom of press found in the First Amendment. In an opinion written by Chief Justice Warren E. Burger, the Court recognized the risks posed to the \"true marketplace of ideas\" by media consolidation and barriers to entry in the newspaper industry.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Morgan v. Bulletin Co.","cite":"85 A.2d 869","y":1952,"court":"Pa.","url":"https://www.courtlistener.com/c/A.2d/85/869/","by":{"2":"25-26"}},{"t":"case","label":"Morse v. Times-Republican Printing Co.","cite":"100 N.W. 867","y":1904,"court":"Iowa","url":"https://www.courtlistener.com/c/N.W./100/867/","by":{"2":"6"}},{"t":"case","label":"Phila. Newspapers, Inc. v. Hepps","cite":"475 U.S. 767","y":1986,"id":"1985/84-1491","sc":1,"sum":"Relying on its reasoning in Gertz v. Robert Welch Inc. (1974), the Court reversed the state court's decision. The Gertz standard for evaluating potentially libelous speech required that \"the plaintiff bear the burden of showing falsity, as well as fault, before recovering damages.\".","sumSrc":"Oyez","by":{"2":"49"}},{"t":"case","label":"Red Lion Broad. Co. v. FCC","cite":"395 U.S. 367","y":1969,"id":"1968/2","sc":1,"sum":"The Court held that the fairness doctrine was consistent with the First Amendment.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Smith v. California","cite":"361 U.S. 147","y":1959,"id":"1959/9","sc":1,"op":1,"sum":"As thus construed and applied, the ordinance violates the freedom of the press which is safeguarded by the Due Process Clause of the Fourteenth Amendment. from invasion by state action.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6, 49"}},{"t":"case","label":"Sw. Airlines v. Saxon","cite":"142 S. Ct. 1783","y":2022,"id":"2021/21-309","sc":1,"sum":"Airplane cargo loaders and ramp supervisors who, like petitioner Saxon, frequently load and unload airplane cargo belong to a “class of workers engaged in foreign or interstate commerce” exempt from the Federal Arbitration Act’s coverage.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"23"}},{"t":"case","label":"Tex. Dep’t of Hous. & Cmty. Affs. v. Inclusive Cmtys. Project","cite":"576 U.S. 519","y":2015,"id":"2014/13-1371","sc":1,"sum":"The Court determined that evidence of disparate impact is sufficient to allege a claim that the defendant violated the Fair Housing Act.","sumSrc":"Oyez","by":{"2":"30-31, 47"}},{"t":"case","label":"Turner Broad. Sys. v. FCC","cite":"512 U.S. 622","y":1994,"id":"1993/93-44","sc":1,"sum":"The Court held that the must-carry provisions were content neutral, thus not a violation of the First Amendment. The rules were not determined by the programming content, but by broadcast method. The rules promote fair competition in television programming.","sumSrc":"Oyez","by":{"2":"24, 30, 50"}},{"t":"case","label":"Unicolors, Inc v. H&M Hennes & Mauritz, L.P.","cite":"142 S. Ct. 941","y":2022,"id":"2021/20-915","sc":1,"sum":"Lack of either factual or legal knowledge can excuse an inaccuracy in a copyright registration under 17 U. S. C. §411(b)(1)(A)’s safe harbor.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"35"}},{"t":"case","label":"Vázquez Rivera v. El Día, Inc.","cite":"641 F. Supp. 668","y":1986,"court":"D.P.R.","url":"https://www.courtlistener.com/c/F.%20Supp./641/668/","by":{"2":"26"}},{"t":"case","label":"Visa Inc. v. Osborn","cite":"137 S. Ct. 289","y":2016,"id":"2016/15-961","sc":1,"sum":"A case in which the Court would have determined whether allegations that members of a business organization agreed to adhere to the organization’s rules and possessed governance rights to the organization are sufficient to plead that there was a conspiracy under the Sherman Act.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"Youmans v. Smith","cite":"47 N.E. 265","y":1897,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E./47/265/","by":{"2":"5"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","by":{"2":"31"}},{"t":"usc","label":"28 U.S.C. § 4102","url":"https://www.law.cornell.edu/uscode/text/28/4102","by":{"2":"31, 47"}},{"t":"usc","label":"35 U.S.C. § 271","url":"https://www.law.cornell.edu/uscode/text/35/271","by":{"2":"51"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"3":"6"}},{"t":"case","label":"Anderson v. TikTok, Inc.","cite":"2022 WL 14742788","y":2022,"court":"E.D. Pa. Oct. 25","by":{"3":"23"}},{"t":"case","label":"Feist Publications, Inc. v. Rural Telephone Service Co., Inc.","cite":"499 U.S. 340","y":1991,"id":"1990/89-1909","sc":1,"sum":"The Court held that the names, towns, and telephone numbers copied by Feist were not original to Rural and therefore were not protected by the copyright in Rural's combined white and yellow pages directory.","sumSrc":"Oyez","by":{"3":"12"}},{"t":"case","label":"Forrester v. White","cite":"484 U.S. 219","y":1988,"id":"1987/86-761","sc":1,"sum":"A state-court judge does not have absolute immunity from a damages suit under § 1983 for his decisions to demote and dismiss a court employee.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"14"}},{"t":"case","label":"Johnson v. Transportation Agency, Santa Clara Cty.","cite":"480 U.S. 616","y":1987,"id":"1986/85-1129","sc":1,"sum":"The Court affirmed the promotion procedures of the Agency. Justice Brennan argued that it was not unreasonable to consider sex as one factor among many in making promotion decisions, and that the Agency's actions did not create an absolute barrier to the advancement of men (a quota system did not exist).","sumSrc":"Oyez","by":{"3":"6"}},{"t":"case","label":"NetChoice, LLC v. Att’y Gen., Fla.","cite":"34 F.4th 1196","y":2022,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/34/1196/","by":{"3":"13"}},{"t":"case","label":"Patterson v. McLean Credit Union","cite":"491 U.S. 164","y":1989,"id":"scdb/1988-115","sc":1,"sum":"Petitioner, a black woman, was employed by respondent credit union as a teller and file coordinator for 10 years until she was laid off. Thereafter, she brought this action in District Court under 42 U. S. C. § 1981, alleging that respondent had harassed her, failed to promote her to accounting clerk, and then discharged her, all because of her race. The District Court determined that a claim for racial harassment …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"6"}},{"t":"usc","label":"17 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/17/101","stext":{"head":"§101. Definitions","paras":[[0,"Except as otherwise provided in this title, as used in this title, the following terms and their variant forms mean the following:"],[1,"An \"anonymous work\" is a work on the copies or phonorecords of which no natural person is identified as author."],[1,"An \"architectural work\" is the design of a building as embodied in any tangible medium of expression, including a building, architectural plans, or drawings. The work includes the overall form as well as the arrangement and composition of spaces and elements in the design, but does not include individual standard features."],[1,"\"Audiovisual works\" are works that consist of a series of related images which are intrinsically intended to be shown by the use of machines, or devices such as projectors, viewers, or electronic equipment, together with accompanying sounds, if any, regardless of the nature of the material objects, such as films or tapes, in which the works are embodied."],[1,"The \"Berne Convention\" is the Convention for the Protection of Literary and Artistic Works, signed at Berne, Switzerland, on September 9, 1886, and all acts, protocols, and revisions thereto."],[1,"The \"best edition\" of a work is the edition, published in the United States at any time before the date of deposit, that the Library of Congress determines to be most suitable for its purposes."],[1,"A person's \"children\" are that person's immediate offspring, whether legitimate or not, and any children legally adopted by that person."],[1,"A \"collective work\" is a work, such as a periodical issue, anthology, or encyclopedia, in which a number of contributions, constituting separate and independent works in themselves, are assembled into a collective whole."],[1,"A \"compilation\" is a work formed by the collection and assembling of preexisting materials or of data that are selected, coordinated, or arranged in such a way that the resulting work as a whole constitutes an original work of authorship. The term \"compilation\" includes collective works."],[1,"A \"computer program\" is a set of statements or instructions to be used directly or indirectly in a computer in order to bring about a certain result."],[1,"\"Copies\" are material objects, other than phonorecords, in which a work is fixed by any method now known or later developed, and from which the work can be perceived, reproduced, or otherwise communicated, either directly or with the aid of a machine or device. The term \"copies\" includes the material object, other than a phonorecord, in which the work is first fixed."],[1,"\"Copyright owner\", with respect to any one of the exclusive rights comprised in a copyright, refers to the owner of that particular right."],[1,"A \"Copyright Royalty Judge\" is a Copyright Royalty Judge appointed under section 802 of this title, and includes any individual serving as an interim Copyright Royalty Judge under such section."],[1,"A work is \"created\" when it is fixed in a copy or phonorecord for the first time; where a work is prepared over a period of time, the portion of it that has been fixed at any particular time constitutes the work as of that time, and where the work has been prepared in different versions, each version constitutes a separate work."],[1,"A \"derivative work\" is a work based upon one or more preexisting works, such as a translation, musical arrangement, dramatization, fictionalization, motion picture version, sound recording, art reproduction, abridgment, condensation, or any other form in which a work may be recast, transformed, or adapted. A work consisting of editorial revisions, annotations, elaborations, or other modifications which, as a whole, represent an original work of authorship, is a \"derivative work\"."],[1,"A \"device\", \"machine\", or \"process\" is one now known or later developed."],[1,"A \"digital transmission\" is a transmission in whole or in part in a digital or other non-analog format."],[1,"To \"display\" a work means to show a copy of it, either directly or by means of a film, slide, television image, or any other device or process or, in the case of a motion picture or other audiovisual work, to show individual images nonsequentially."],[1,"An \"establishment\" is a store, shop, or any similar place of business open to the general public for the primary purpose of selling goods or services in which the majority of the gross square feet of space that is nonresidential is used for that purpose, and in which nondramatic musical works are performed publicly."],[1,"The term \"financial gain\" includes receipt, or expectation of receipt, of anything of value, including the receipt of other copyrighted works."],[1,"A work is \"fixed\" in a tangible medium of expression when its embodiment in a copy or phonorecord, by or under the authority of the author, is sufficiently permanent or stable to permit it to be perceived, reproduced, or otherwise communicated for a period of more than transitory duration. A work consisting of sounds, images, or both, that are being transmitted, is \"fixed\" for purposes of this title if a fixation of the work is being made simultaneously with its transmission."],[1,"A \"food service or drinking establishment\" is a restaurant, inn, bar, tavern, or any other similar place of business in which the public or patrons assemble for the primary purpose of being served food or drink, in which the majority of the gross square feet of space that is nonresidential is used for that purpose, and in which nondramatic musical works are performed publicly."],[1,"The \"Geneva Phonograms Convention\" is the Convention for the Protection of Producers of Phonograms Against Unauthorized Duplication of Their Phonograms, concluded at Geneva, Switzerland, on October 29, 1971."],[1,"The \"gross square feet of space\" of an establishment means the entire interior space of that establishment, and any adjoining outdoor space used to serve patrons, whether on a seasonal basis or otherwise."],[1,"The terms \"including\" and \"such as\" are illustrative and not limitative."],[1,"An \"international agreement\" is—"],[2,"(1) the Universal Copyright Convention;"],[2,"(2) the Geneva Phonograms Convention;"],[2,"(3) the Berne Convention;"],[2,"(4) the WTO Agreement;"],[2,"(5) the WIPO Copyright Treaty;"],[2,"(6) the WIPO Performances and Phonograms Treaty; and"],[2,"(7) any other copyright treaty to which the United States is a party."],[1,"A \"joint work\" is a work prepared by two or more authors with the intention that their contributions be merged into inseparable or interdependent parts of a unitary whole."],[1,"\"Literary works\" are works, other than audiovisual works, expressed in words, numbers, or other verbal or numerical symbols or indicia, regardless of the nature of the material objects, such as books, periodicals, manuscripts, phonorecords, film, tapes, disks, or cards, in which they are embodied."],[1,"The term \"motion picture exhibition facility\" means a movie theater, screening room, or other venue that is being used primarily for the exhibition of a copyrighted motion picture, if such exhibition is open to the public or is made to an assembled group of viewers outside of a normal circle of a family and its social acquaintances."],[1,"\"Motion pictures\" are audiovisual works consisting of a series of related images which, when shown in succession, impart an impression of motion, together with accompanying sounds, if any."],[1,"To \"perform\" a work means to recite, render, play, dance, or act it, either directly or by means of any device or process or, in the case of a motion picture or other audiovisual work, to show its images in any sequence or to make the sounds accompanying it audible."],[1,"A \"performing rights society\" is an association, corporation, or other entity that licenses the public performance of nondramatic musical works on behalf of copyright owners of such works, such as the American Society of Composers, Authors and Publishers (ASCAP), Broadcast Music, Inc. (BMI), and SESAC, Inc."],[1,"\"Phonorecords\" are material objects in which sounds, other than those accompanying a motion picture or other audiovisual work, are fixed by any method now known or later developed, and from which the sounds can be perceived, reproduced, or otherwise communicated, either directly or with the aid of a machine or device. The term \"phonorecords\" includes the material object in which the sounds are first fixed."],[1,"\"Pictorial, graphic, and sculptural works\" include two-dimensional and three-dimensional works of fine, graphic, and applied art, photographs, prints and art reproductions, maps, globes, charts, diagrams, models, and technical drawings, including architectural plans. Such works shall include works of artistic craftsmanship insofar as their form but not their mechanical or utilitarian aspects are concerned; the design of a useful article, as defined in this section, shall be considered a pictorial, graphic, or sculptural work only if, and only to the extent that, such design incorporates pictorial, graphic, or sculptural features that can be identified separately from, and are capable of existing independently of, the utilitarian aspects of the article."],[1,"For purposes of section 513, a \"proprietor\" is an individual, corporation, partnership, or other entity, as the case may be, that owns an establishment or a food service or drinking establishment, except that no owner or operator of a radio or television station licensed by the Federal Communications Commission, cable system or satellite carrier, cable or satellite carrier service or programmer, provider of online services or network access or the operator of facilities therefor, telecommunications company, or any other such audio or audiovisual service or programmer now known or as may be developed in the future, commercial subscription music service, or owner or operator of any other transmission service, shall under any circumstances be deemed to be a proprietor."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/17/101?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§101. Definitions","tname":"Copyrights","by":{"3":"12"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(b)(6)"],"by":{"3":"1"}}]};